// === PLAN VE KULLANICI BİLGİLERİ ===
const body = $input.first().json.body;
const { kullanici_id, email, ad, soyad, plan, ip, gsm } = body;

if (!kullanici_id || !email || !ad || !plan) {
  throw new Error('EKSIK_ALAN: kullanici_id, email, ad, plan zorunlu');
}

const planlar = {
  'premium_6ay':    { tutar: 600.0,  label: '6 Aylık Premium - YKS KAFA', ay: 6 },
  'premium_yillik': { tutar: 1000.0, label: 'Yıllık Premium - YKS KAFA', ay: 12 }
};
if (!planlar[plan]) throw new Error('GECERSIZ_PLAN');

const secilen = planlar[plan];
const conversationId = 'ykskafa-' + kullanici_id + '-' + Date.now();
const basketId = 'basket-' + Date.now();

// === iyzico HMAC-SHA256 Authorization Oluştur (IYZWSv2) ===
// randomKey = timestamp + 9 haneli sayı
const randomKey = new Date().getTime().toString() + '123456789';
const apiKey    = $env.IYZICO_API_KEY;
const secretKey = $env.IYZICO_SECRET_KEY;
const uriPath   = '/payment/iyzipos/checkoutform/initialize/auth/ecom';

// Payload: randomKey + uriPath + requestBody (henüz body oluşturulmadı, imza için placeholder)
// NOT: iyzico imzası için body'yi önceden JSON stringify ederek oluşturuyoruz
const requestBody = {
  locale: 'tr',
  conversationId,
  price: secilen.tutar.toFixed(2),
  paidPrice: secilen.tutar.toFixed(2),
  currency: 'TRY',
  basketId,
  paymentGroup: 'PRODUCT',
  callbackUrl: $env.IYZICO_CALLBACK_URL,
  enabledInstallments: [1, 2, 3],
  buyer: {
    id: kullanici_id,
    name: ad,
    surname: soyad || ad,
    identityNumber: '11111111111',
    email: email,
    gsmNumber: gsm || '+905000000000',
    registrationDate: '2024-01-01 00:00:00',
    lastLoginDate: new Date().toISOString().replace('T', ' ').slice(0, 19),
    registrationAddress: 'Istanbul',
    city: 'Istanbul',
    country: 'Turkey',
    zipCode: '34000',
    ip: ip || '85.34.78.112'
  },
  shippingAddress: {
    contactName: ad + ' ' + (soyad || ''),
    city: 'Istanbul',
    country: 'Turkey',
    address: 'Istanbul',
    zipCode: '34000'
  },
  billingAddress: {
    contactName: ad + ' ' + (soyad || ''),
    city: 'Istanbul',
    country: 'Turkey',
    address: 'Istanbul',
    zipCode: '34000'
  },
  basketItems: [
    {
      id: plan,
      name: secilen.label,
      category1: 'Eğitim',
      itemType: 'VIRTUAL',
      price: secilen.tutar.toFixed(2)
    }
  ]
};

const bodyStr = JSON.stringify(requestBody);
const payload = randomKey + uriPath + bodyStr;

// HMAC-SHA256 ile imzala (Node.js crypto - n8n'de require desteklenir)
const crypto = require('crypto');
const signature = crypto.createHmac('sha256', secretKey).update(payload).digest('hex');

// Base64 encode: "apiKey:xxx&randomKey:xxx&signature:xxx"
const authStr = 'apiKey:' + apiKey + '&randomKey:' + randomKey + '&signature:' + signature;
const base64Auth = Buffer.from(authStr).toString('base64');
const authHeader = 'IYZWSv2 ' + base64Auth;

return [{ json: {
  requestBody,
  bodyStr,
  authHeader,
  conversationId,
  basketId,
  plan,
  plan_label: secilen.label,
  tutar: secilen.tutar,
  ay: secilen.ay,
  kullanici_id,
  email,
  ad,
  soyad: soyad || ad
}}];

const iyzicoResp = $input.first().json;
const prev = $('iyzico Auth & Request Hazırla').first().json;

if (iyzicoResp.status !== 'success') {
  throw new Error('IYZICO_HATA: ' + iyzicoResp.errorMessage + ' (kod: ' + iyzicoResp.errorCode + ')');
}

return [{ json: {
  token: iyzicoResp.token,
  checkoutFormContent: iyzicoResp.checkoutFormContent,
  paymentPageUrl: iyzicoResp.paymentPageUrl || null,
  conversationId: prev.conversationId,
  basketId: prev.basketId,
  plan: prev.plan,
  plan_label: prev.plan_label,
  tutar: prev.tutar,
  ay: prev.ay,
  kullanici_id: prev.kullanici_id,
  email: prev.email,
  ad: prev.ad
}}];
